    const faceImage=face.image||card.image,faceName=face.name||card.name;if(card.counterMarker){const isPtCounter=card.counterMarker==="+1/+1"||card.counterMarker==="-1/-1";if(!isPtCounter)el.style.setProperty('--counter-bg',counterMarkerColor(card.counterMarker));el.innerHTML=isPtCounter?`<span class="counter-marker-symbol" aria-hidden="true">${card.counterMarker==="+1/+1"?'+':'−'}</span><span class="counter-marker-values">${esc(formatCounterValues(card.counterPower,card.counterToughness)||card.counterMarker)}</span>`:`<img class="counter-marker-image" src="${counterIconUrl(card.counterMarker)}" alt="${escAttr(card.counterMarker)}"><span class="counter-marker-values">${formatCounterValues(card.counterPower,card.counterToughness)}</span>`;}else if(faceImage){const img=document.createElement('img');img.src=faceImage;img.alt=faceName;img.loading='lazy';if(isFlipLayout(card.layout)&&card.faceIndex%2)img.style.transform='rotate(180deg)';img.onerror=()=>{img.remove();el.classList.add('no-image');el.insertAdjacentHTML('beforeend',`<span class="card-fallback">${esc(faceName)}</span>`);};el.append(img);}else{el.insertAdjacentHTML('beforeend',`<span class="card-fallback">${esc(faceName)}</span>`);}
