  function moveCard(cardId,from,to,position){const src=state[from],i=src?.findIndex(c=>c.id===cardId);if(i<0||!src)return;const [c]=src.splice(i,1);c.zone=to;c.tapped=false;c.attacking=false;c.blocking=null;c.blockers=[];if(position){c.x=position.x;c.y=position.y;}if(to==='commandZone'&&c.isCommander){const duplicate=state.commandZone.findIndex(other=>other.id===c.id||(other.isCommander&&other.ownerId===c.ownerId&&other.name===c.name));if(duplicate>=0){const [existing]=state.commandZone.splice(duplicate,1);c.commanderTax=Math.max(Number(c.commanderTax)||0,Number(existing.commanderTax)||0);if(existing.id!==c.id)sharedCards?.delete(existing.id);}c.commanderTax=(Number(c.commanderTax)||0)+2;}state[to].push(c);save();render();syncCard(c,to);syncCounts();logAction(`moved ${c.name} to ${zoneName(to)}`);}
