  function deleteCard(cardId,zone){const cards=state[zone],index=cards?.findIndex(c=>c.id===cardId);if(index<0||!cards)return;const [card]=cards.splice(index,1);if(sharedCards)sharedCards.delete(cardId);save();render();syncCounts();logAction(`a supprimé ${card.name}`);}
