  const COUNTER_TYPES=[['Enchant','ability-static.svg'],['First strike','ability-firststrike.svg'],['Double strike','ability-doublestrike.svg'],['Deathtouch','ability-deathtouch.svg'],['Lifelink','ability-lifelink.svg'],['Defender','ability-defender.svg'],['Flying','ability-flying.svg'],['Reach','ability-reach.svg'],['Hexproof','ability-hexproof.svg'],['Trample','ability-trample.svg'],['Haste','ability-haste.svg'],['Equip','ability-activated.svg'],['Vigilance','ability-vigilance.svg'],['Indestructible','ability-indestructible.svg'],['Menace','ability-menace.svg'],['Protection','counter-shield.svg'],['Flash','ability-flash.svg'],['Prowess','ability-prowess.svg'],['Ward','ability-ward.svg'],['Scry','ability-surveil.svg']];
