  function counterMarkerColor(kind){return ({Enchant:'#aaa5a7','First strike':'#f2e4b5','Double strike':'#f2e4b5',Deathtouch:'#eca084',Lifelink:'#f2e4b5',Defender:'#a8c5df',Flying:'#f2e4b5',Reach:'#b7ccc3',Hexproof:'#b7ccc3',Trample:'#b7ccc3',Haste:'#eca084',Equip:'#b7ccc3',Vigilance:'#b7ccc3',Indestructible:'#b7ccc3',Menace:'#eca084',Protection:'#f2e4b5',Flash:'#f2e4b5',Prowess:'#b7ccc3',Ward:'#f2e4b5',Scry:'#f2e4b5'})[kind]||'#f2e4b5';}
