  function repositionCard(cardId,position){const i=state.battlefield.findIndex(c=>c.id===cardId);if(i<0)return;const [card]=state.battlefield.splice(i,1);card.x=position.x;card.y=position.y;state.battlefield.push(card);save();render();syncCard(card,'battlefield');}
