  function showCardMenu(e,card,zone){$$('.card-menu').forEach(x=>x.remove());const menu=document.createElement('div');menu.className='card-menu aura-card-menu';menu.dataset.cardId=card.id;menu.style.left=`${Math.max(5,Math.min(e.clientX,innerWidth-210))}px`;menu.style.top=`${Math.max(5,Math.min(e.clientY,innerHeight-460))}px`;document.body.append(menu);const add=(label,key,fn,disabled=false)=>{const b=document.createElement('button');b.disabled=disabled;b.innerHTML=`<span>${label}</span>${key?`<kbd>${key}</kbd>`:''}`;b.onclick=()=>{menu.remove();fn();};menu.append(b);};add('Tap','Space',()=>toggleHovered('tap',card.id),zone!=='battlefield');add('Untap all','X',untapLocal);add('Summoning sick','Z',()=>toggleHovered('sick',card.id),zone!=='battlefield');add('Flip','F',()=>toggleHovered('flip',card.id));add('Add +1/+1 counter','U',()=>toggleHovered('counter+',card.id),zone!=='battlefield');add('Remove +1/+1 counter','I',()=>toggleHovered('counter-',card.id),zone!=='battlefield'||!card.counters);add('Add -1/-1 counter','J',()=>toggleHovered('minus-counter+',card.id),zone!=='battlefield');add('Remove -1/-1 counter','N',()=>toggleHovered('minus-counter-',card.id),zone!=='battlefield'||!card.minusCounters);add('Copy / clone','K',()=>cloneCard(card,zone));add('Delete','Backspace',()=>deleteCard(card.id,zone));menu.insertAdjacentHTML('beforeend','<hr>');if(card.isCommander&&zone!=='commandZone')add('Return to command zone','R',()=>moveCard(card.id,zone,'commandZone'));for(const [label,key,to] of [['Hand','H','hand'],['Discard','D','graveyard'],['Exile','S','exile'],['To deck top','T','top'],['To deck bottom','Y','bottom'],['Sideboard','B','reserve']])add(label,key,()=>to==='top'||to==='bottom'?moveToLibrary(card.id,zone,to):moveCard(card.id,zone,to),to===zone);}
