  function showHoverCard(card){const face=visibleFace(card),preview=$('#hover-card-preview'),img=$('img',preview),title=$('.hover-card-title',preview);if(card.facedown){hideHoverCard();return;}title.textContent=(face.name||card.name)+(face.type?` · ${face.type}`:'');const image=face.image||card.image;if(image){img.hidden=false;img.alt=face.name||card.name;img.onerror=()=>preview.classList.add('text-only');img.onload=()=>preview.classList.remove('text-only');preview.classList.remove('text-only');img.src=image;}else{img.hidden=true;img.removeAttribute('src');preview.classList.add('text-only');}preview.classList.add('visible');preview.setAttribute('aria-hidden','false');}
  function hideHoverCard(){const preview=$('#hover-card-preview');if(!preview)return;preview.classList.remove('visible');preview.setAttribute('aria-hidden','true');}
  function showCard(c){const face=visibleFace(c),name=face.name||c.name,image=face.image||c.image,type=face.type||c.type,manaCost=face.manaCost||c.manaCost,oracle=face.oracle||c.oracle,power=face.power||c.power,toughness=face.toughness||c.toughness,stats=/\bcreature\b/i.test(type||'')?`<p class="card-stats">${esc(manaCost||'')} · ${esc(power||'0')}/${esc(toughness||'0')}</p>`:'';$('#card-detail').innerHTML=`<div class="card-detail">${image?`<img src="${escAttr(image)}" alt="${escAttr(name)}">`:'<div class="deck-thumb">✦</div>'}<div><h3>${esc(name)}</h3><p>${esc(manaCost||'')}</p><p>${esc(type||'Magic card')}</p>${stats}<p>${esc(oracle||'Card text unavailable.')}</p>${c.printsUri?'<button class="secondary" id="prints-btn">Other prints</button>':''}</div></div>`;$('#card-dialog').showModal();$('#prints-btn')?.addEventListener('click',()=>showPrints(c));}
  // P2P requests are CRDT records: viewers can inspect only zones the owner has
  // shared, and only the owner can mark a requested card transfer accepted.
  function openZoneViewer(zone,view='top',ownerId=null){viewerZone=zone;viewerOwnerId=ownerId;libraryView=view;viewerAccessRequestId=null;if(ownerId&&zone==='library'){const access=zoneViewRequest(ownerId);if(access?.status==='accepted')viewerAccessRequestId=access.id;else if(access?.status==='pending')viewerAccessRequestId=access.id;else viewerAccessRequestId=createZoneRequest(ownerId,'view-library','library')?.id||null;}renderZoneViewer();$('#zone-view-dialog').showModal();}
  function zoneViewRequest(ownerId){return [...(sharedRequests?.entries()||[])].map(([requestId,request])=>({...request,id:requestId})).filter(request=>request.action==='view-library'&&request.ownerId===ownerId&&request.requesterId===localPlayerId).sort((a,b)=>b.createdAt-a.createdAt)[0]||null;}
  function openRemoteZone(ownerId,zone){if(zone==='library'&&!sharedRequests){toast('Connecte-toi à une room pour demander l’accès.');return;}openZoneViewer(zone,zone==='library'?'all':'top',ownerId);}
  function createZoneRequest(ownerId,action,zone,cardId='',cardName=''){if(!sharedRequests)return null;const duplicate=[...sharedRequests.values()].find(request=>request.ownerId===ownerId&&request.requesterId===localPlayerId&&request.action===action&&request.cardId===cardId&&request.status==='pending');if(duplicate){toast('Demande déjà envoyée; en attente du propriétaire.');return duplicate;}const request={ownerId,requesterId:localPlayerId,requesterName:state.playerName||'Planeswalker',action,zone,cardId,cardName,status:'pending',createdAt:Date.now()};const requestId=id();sharedRequests.set(requestId,request);toast(action==='view-library'?'Demande d’accès à la bibliothèque envoyée.':'Demande de carte envoyée au propriétaire.');return {id:requestId,...request};}
  function requestRemoteCard(card){if(!viewerOwnerId)return;const request=createZoneRequest(viewerOwnerId,'take-card',viewerZone,card.id,card.name);if(request)logAction(`demande à ${room.players.find(p=>p.id===viewerOwnerId)?.name||'un joueur'} la carte ${card.name}`,true);}
  function refreshZoneRequests(){if(!sharedRequests)return;for(const [requestId,request] of sharedRequests.entries()){if(request.requesterId!==localPlayerId||request.action!=='take-card'||processedZoneRequests.has(requestId))continue;if(request.status==='accepted'&&request.card){processedZoneRequests.add(requestId);if(!state.hand.some(card=>card.id===request.card.id)){state.hand.push({...request.card,zone:'hand',ownerId:localPlayerId});save();syncCounts();render();logAction(`${request.card.name} reçu de ${room?.players.find(p=>p.id===request.ownerId)?.name||'un joueur'}`,true);}}else if(request.status==='rejected'){processedZoneRequests.add(requestId);toast(`Le propriétaire a refusé la demande pour ${request.cardName||'cette carte'}.`);}}renderZoneRequests();if($('#zone-view-dialog')?.open&&viewerOwnerId)renderZoneViewer();}
  function renderZoneRequests(){if(!sharedRequests||!$('#zone-request-dialog'))return;const pending=[...sharedRequests.entries()].filter(([,request])=>request.ownerId===localPlayerId&&request.status==='pending'),host=$('#zone-request-list'),openButton=$('#zone-requests-open');if(openButton)openButton.classList.toggle('hidden',!pending.length);host.innerHTML='';if(!pending.length){if($('#zone-request-dialog').open)$('#zone-request-dialog').close();return;}for(const [requestId,request] of pending){const row=document.createElement('div');row.className='zone-request-row';const isView=request.action==='view-library',zone=request.zone==='library'?'ta bibliothèque':'ton cimetière';row.innerHTML=`<div><strong>${esc(request.requesterName||'Un joueur')}</strong><span>${isView?'demande à consulter':`demande la carte ${esc(request.cardName||'sélectionnée')} de`} ${zone}.</span></div><div class="zone-request-actions"><button class="secondary" data-zone-reject="${escAttr(requestId)}">Refuser</button><button class="primary" data-zone-accept="${escAttr(requestId)}">Accepter</button></div>`;host.append(row);}host.querySelectorAll('[data-zone-accept]').forEach(button=>button.onclick=()=>resolveZoneRequest(button.dataset.zoneAccept,true));host.querySelectorAll('[data-zone-reject]').forEach(button=>button.onclick=()=>resolveZoneRequest(button.dataset.zoneReject,false));if(!$('#zone-request-dialog').open)$('#zone-request-dialog').showModal();}
