  async function showPrints(card){try{const r=await fetch(card.printsUri);if(!r.ok)throw 0;const data=await r.json();const prints=data.data.slice(0,30).filter(x=>x.image_uris?.normal||x.card_faces?.[0]?.image_uris?.normal);const choice=prompt('Choisissez une impression par numéro :\n'+prints.map((p,i)=>`${i+1}. ${(p.set_name||p.set)?.trim()} · ${p.collector_number}`).join('\n'));const n=Number(choice)-1;if(Number.isInteger(n)&&prints[n]){const p=prints[n],face=p.card_faces?.[0];card.image=p.image_uris?.normal||face?.image_uris?.normal;card.small=p.image_uris?.small||face?.image_uris?.small;save();render();showCard(card);}}catch{toast('Impossible de charger les impressions Scryfall.');}}
