  function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}function escAttr(s=''){return esc(s);}
  function openImport(){resetImporter();$('#import-dialog').showModal();}
  function resetImporter(){$('#deck-text').value='';$('#deck-name').value='';$('#moxfield-url').value='';$('#preview').classList.add('hidden');$('#preview-btn').classList.remove('hidden');$('#confirm-import').classList.add('hidden');$('#back-edit').classList.add('hidden');$('#import-error').classList.add('hidden');$('#import-status').textContent='';importRows=[];}
  async function analyze(){
    const input=$('#deck-text').value;importRows=parseDeck(input);if(!importRows.length){showError('Aucune ligne de carte reconnue. Utilisez « quantité Nom de carte », par exemple « 1 Sol Ring ».');return;}
    $('#preview-btn').disabled=true;$('#import-error').classList.add('hidden');$('#import-status').textContent='Recherche des cartes sur Scryfall…';$('#preview').classList.remove('hidden');
    let done=0;for(const row of importRows){try{row.card=await lookupCard(row.name);row.error='';}catch(e){row.error=e.message;row.card=null;}done++;$('#import-status').textContent=`Recherche des cartes… ${done}/${importRows.length}`;renderPreview();}
    $('#preview-btn').disabled=false;$('#import-status').textContent=`${importRows.filter(x=>x.card).length}/${importRows.length} cartes reconnues. Vous pouvez corriger les noms signalés.`;$('#preview-btn').classList.add('hidden');$('#confirm-import').classList.remove('hidden');$('#back-edit').classList.remove('hidden');
  }
  function renderPreview(){const preview=$('#preview');preview.innerHTML=`<div class="preview-head"><b>Aperçu · ${importRows.reduce((a,c)=>a+c.qty,0)} cartes</b><span class="muted small">${new Set(importRows.map(x=>x.section)).size} section(s)</span></div>`;let prev='';const list=document.createElement('div');list.className='preview-list';for(const [i,row] of importRows.entries()){if(row.section!==prev){prev=row.section;const h=document.createElement('div');h.className='section-chip';h.style.gridColumn='1/-1';h.textContent=prev;list.append(h);}const line=document.createElement('div');line.className='preview-row'+(row.card?'':' issue');line.innerHTML=`${row.card?.image?`<img src="${escAttr(row.card.small||row.card.image)}" alt="">`:'<span style="width:27px;color:#ef9e90">!</span>'}<span class="qty">${row.qty}×</span><input aria-label="Nom de la carte ${i+1}" value="${escAttr(row.card?.name||row.name)}" style="background:transparent;border:0;color:inherit;padding:3px;font-size:10px;min-width:0">${row.card?'<span class="muted">✓</span>':'<button class="text-button retry-card">Rechercher</button>'}`;line.querySelector('input').onchange=e=>{row.name=e.target.value;row.card=null;row.error='À rechercher';renderPreview();};line.querySelector('.retry-card')?.addEventListener('click',async()=>{const btn=line.querySelector('button');btn.disabled=true;try{row.card=await lookupByFuzzy(row.name);row.name=row.card.name;row.error='';}catch{row.error='Carte introuvable';}renderPreview();});list.append(line);}preview.append(list);}
  function showError(t){const e=$('#import-error');e.textContent=t;e.classList.remove('hidden');}
  function finishImport(){const valid=importRows.filter(x=>x.card);if(!valid.length){showError('Aucune carte reconnue. Corrigez au moins une carte avant de continuer.');return;}const cards=valid.map(r=>({...r.card,qty:r.qty,section:r.section}));const deck={id:id(),name:$('#deck-name').value.trim()||'Deck sans nom',format:'Format libre',cards,createdAt:Date.now()};state.decks.unshift(deck);save();renderDecks();$('#import-dialog').close();toast(`${deck.name} ajouté à la bibliothèque`);if(!state.currentDeck)loadDeck(deck.id);else $('#deck-picker').showModal();}
  function extractMoxfieldId(value){const url=validMoxfieldUrl(value);return url?.pathname.match(/^\/decks\/([\w-]+)/)?.[1]||null;}
  function moxfieldDeckCards(data){
    const rows=[],boards=data.boards||{};
    for(const [boardKey,section] of [['commanders','Commander'],['mainboard','Mainboard'],['companions','Companion'],['sideboard','Sideboard'],['maybeboard','Maybeboard']]){
      const entries=boards[boardKey]?.cards;if(!entries)continue;
      // Moxfield's `id` is a catalog ID; its board key/uniqueCardId identifies the
      // selected printing and is the ID used by the Moxfield image CDN.
      for(const [entryId,entry] of Object.entries(entries)){
        const card=entry.card||entry,name=card.name||entry.name;if(!name)continue;
        const faces=(card.card_faces||[]).map((face,index)=>({name:face.name||name,image:scryfallPrintImage(card.scryfall_id,index===1?'back':'front')||`https://assets.moxfield.net/cards/card-${encodeURIComponent(face.uniqueCardId||face.id||card.uniqueCardId||entryId)}-normal.webp`,oracle:face.oracle_text||'',type:face.type_line||'',manaCost:face.mana_cost||'',power:face.power||'',toughness:face.toughness||''}));
        const printId=card.uniqueCardId||entryId||card.id;
        // Moxfield's CDN can return an unrelated card for some face IDs; its
        // Scryfall UUID is the exact selected printing and maps to stable art.
        const image=scryfallPrintImage(card.scryfall_id)||faces[0]?.image||(printId?`https://assets.moxfield.net/cards/card-${encodeURIComponent(printId)}-normal.webp`:null);
        rows.push({name,image,small:image,faces:faces.length>1&&['transform','modal_dfc','reversible_card','double_faced_token','flip'].includes(String(card.layout||'').toLowerCase())?faces:[],oracle:card.oracle_text||faces[0]?.oracle||'',type:card.type_line||card.type||faces[0]?.type||'',manaCost:card.mana_cost||faces[0]?.manaCost||'',power:card.power||faces[0]?.power||'',toughness:card.toughness||faces[0]?.toughness||'',scryfallId:card.scryfall_id||null,set:card.set||'',collectorNumber:card.cn||'',moxfieldPrintId:printId,printsUri:null,layout:card.layout||'',qty:Math.max(1,Number(entry.quantity||entry.qty||1)),section});
      }
    }
    return rows;
  }
  function scryfallPrintImage(scryfallId,face='front'){
    if(!/^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/i.test(scryfallId||''))return null;
    const id=scryfallId.toLowerCase();
    return `https://cards.scryfall.io/normal/${face}/${id[0]}/${id[1]}/${id}.jpg`;
  }
  function exactPrintArt(card){
    if(!card?.scryfallId)return {};
    const image=scryfallPrintImage(card.scryfallId);
    if(!image)return {};
    const faces=(card.faces||[]).map((face,index)=>({...face,image:scryfallPrintImage(card.scryfallId,index===1?'back':'front')||face.image}));
    return {image,small:image,...(faces.length?{faces}:{})};
  }
  async function importMoxfieldDeck(){
    const deckId=extractMoxfieldId($('#moxfield-url').value);
    if(!deckId){showError('Colle un lien Moxfield valide, par exemple https://moxfield.com/decks/…');return;}
    const button=$('#moxfield-import');button.disabled=true;$('#import-error').classList.add('hidden');$('#import-status').textContent='Chargement du deck public…';
    try{
      const apiUrl=`https://api2.moxfield.com/v3/decks/all/${encodeURIComponent(deckId)}`;
      // GitHub Pages is static and Moxfield does not grant it browser CORS access.
      // cors.tools relays this public GET; a self-hosted Worker can replace it in config.js.
      const configuredProxy=String(window.MTG_TABLE_CONFIG?.moxfieldProxyUrl||'').trim().replace(/\/$/,'');
      const requestUrl=configuredProxy?`${configuredProxy}/${encodeURIComponent(deckId)}`:`https://cors.tools/proxy?url=${encodeURIComponent(apiUrl)}`;
      const response=await fetch(requestUrl,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(25000)});
      let payload;try{payload=await response.json();}catch{payload=null;}
      if(!response.ok){const upstreamError=typeof payload?.error==='string'?payload.error:payload?.error?.message;throw new Error(upstreamError||`Impossible de lire ce deck (HTTP ${response.status}). Vérifie qu’il est public.`);}
      const data=payload?.deck||payload,cards=moxfieldDeckCards(data);
      if(!cards.length)throw new Error('Aucune carte trouvée. Vérifie que le deck est public et contient une liste.');
      const sourceUrl=`https://moxfield.com/decks/${deckId}`,existing=state.decks.find(item=>item.sourceUrl===sourceUrl);
      const deck={id:existing?.id||id(),name:data.name||'Deck Moxfield',format:data.format||'Format libre',sourceUrl,cards,createdAt:Date.now()};
      if(existing)state.decks=state.decks.map(item=>item.id===existing.id?deck:item);else state.decks.unshift(deck);
      save();renderDecks();$('#import-dialog').close();toast(existing?`${deck.name} actualisé depuis Moxfield`:`${deck.name} importé depuis Moxfield`);
      if(!state.currentDeck)loadDeck(deck.id);else $('#deck-picker').showModal();
    }catch(error){
      const message=error?.name==='TimeoutError'?'Le service d’import met trop de temps à répondre. Réessaie dans un instant.':error instanceof TypeError?'Le service de lecture du deck est momentanément inaccessible. Réessaie plus tard.':error.message||'Impossible de charger le deck Moxfield.';
      $('#import-status').textContent='';showError(message);
    }finally{button.disabled=false;}
  }
  function drawCards(n=1){if(!state.library.length){toast('Your library is empty.');return;}let drew=0;for(let i=0;i<n&&state.library.length;i++){const c=state.library.shift();c.zone='hand';state.hand.push(c);drew++;}save();render();syncCounts();logAction(`drew ${drew} card${drew===1?'':'s'}`);}
  function askCount(label,max=state.library.length){const raw=prompt(`${label} (1–${max})`,'1');if(raw===null)return 0;const count=Number.parseInt(raw,10);if(!Number.isFinite(count)||count<1){toast('Entre un nombre valide.');return 0;}return Math.min(count,max);}
  function moveTopLibraryCard(destination){const card=state.library.shift();if(!card){toast('Votre bibliothèque est vide.');return;}card.zone=destination;card.tapped=false;card.attacking=false;card.blocking=null;card.blockers=[];if(destination==='battlefield'){card.x=48;card.y=48;}state[destination].push(card);save();render();syncCard(card,destination);syncCounts();logAction(`a déplacé la carte du dessus vers ${zoneName(destination)}`);}
  function millCards(count){if(!state.library.length){toast('Votre bibliothèque est vide.');return;}let milled=0;while(milled<count&&state.library.length){const card=state.library.shift();card.zone='graveyard';state.graveyard.push(card);syncCard(card,'graveyard');milled++;}save();render();syncCounts();logAction(`a meulé ${milled} carte${milled===1?'':'s'}`);}
  function scryOrSurveil(mode){const count=askCount(mode==='scry'?'Scry combien de cartes':'Surveil combien de cartes');if(!count)return;const top=state.library.slice(0,count),description=top.map((card,index)=>`${index+1}. ${card.name}`).join('\n');const raw=prompt(`${mode==='scry'?'Regarder ces cartes et choisir celles à mettre dessous':'Regarder ces cartes et choisir celles à mettre au cimetière'} (numéros séparés par des virgules).\n\n${description}\n\nLaisser vide pour ne rien déplacer.`, '');if(raw===null)return;const selected=new Set(raw.split(',').map(value=>Number.parseInt(value.trim(),10)-1).filter(index=>Number.isInteger(index)&&index>=0&&index<top.length));if(!selected.size){logAction(`${mode==='scry'?'scried':'surveilled'} ${count} card${count===1?'':'s'}`);return;}const chosen=top.filter((_,index)=>selected.has(index)),chosenIds=new Set(chosen.map(card=>card.id));if(mode==='scry'){state.library=state.library.filter(card=>!chosenIds.has(card.id)).concat(chosen);logAction(`a fait regard ${count} carte${count===1?'':'s'} et en a mis ${chosen.length} dessous`);}else{state.library=state.library.filter(card=>!chosenIds.has(card.id));for(const card of chosen){card.zone='graveyard';state.graveyard.push(card);syncCard(card,'graveyard');}logAction(`a regardé ${count} carte${count===1?'':'s'} avec surveil et en a mis ${chosen.length} au cimetière`);}save();render();syncCounts();}
  function mulligan(){if(!state.library.length&&!state.hand.length){toast('Aucune carte à mélanger.');return;}if(!confirm(`Faire un mulligan${mulliganCount?` supplémentaire (${mulliganCount+1}e)` :''} ? Tu repiocheras 7 cartes, puis remettras ${mulliganCount+1} carte${mulliganCount?'s':''} sous ta bibliothèque quand tu garderas ta main.`))return;state.library=shuffleArray([...state.hand,...state.library]);state.hand=[];const count=Math.min(7,state.library.length);for(let i=0;i<count;i++){const card=state.library.shift();card.zone='hand';state.hand.push(card);}mulliganCount++;save();render();syncCounts();logAction(`a fait son ${mulliganCount}${mulliganCount===1?'er':'e'} mulligan et a repioché ${count} cartes`);}
